89	
90	#if defined(CONFIG_I2C) && defined(CONFIG_SYSTEM_I2CTOOL)
91	static void stm32_i2c_register(int bus)
92	{
93	  struct i2c_master_s *i2c;
94	  int ret;
95	
96	  i2c = stm32_i2cbus_initialize(bus);
97	  if (i2c == NULL)
98	    {
99	      syslog(LOG_ERR, "ERROR: Failed to get I2C%d interface\n", bus);
100	    }
101	  else
102	    {
103	      ret = i2c_register(i2c, bus);
104	      if (ret < 0)
105	        {
106	          syslog(LOG_ERR, "ERROR: Failed to register I2C%d driver: %d\n",
107	                 bus, ret);
108	          stm32_i2cbus_uninitialize(i2c);
109	        }
110	    }
111	}
112	#endif
