154	 *   CONFIG_NSH_ARCHINIT:
155	 *     Called from the NSH library
156	 *
157	 ****************************************************************************/
158	
159	int stm32_bringup(void)
160	{
161	  int ret = OK;
162	#ifdef HAVE_RTC_DRIVER
163	  struct rtc_lowerhalf_s *lower;
164	#endif
165	#ifdef CONFIG_ONESHOT
166	  struct oneshot_lowerhalf_s *os;
167	#endif
168	
169	  UNUSED(ret);
170	
171	#if defined(CONFIG_I2C) && defined(CONFIG_SYSTEM_I2CTOOL)
172	  stm32_i2ctool();
173	#endif
174	
175	#ifdef CONFIG_FS_PROCFS
176	  /* Mount the procfs file system */
177	
178	  ret = nx_mount(NULL, STM32_PROCFS_MOUNTPOINT, "procfs", 0, NULL);
179	  if (ret < 0)
180	    {
181	      syslog(LOG_ERR,
182	             "ERROR: Failed to mount the PROC filesystem: %d\n",  ret);
183	    }
184	#endif /* CONFIG_FS_PROCFS */
185	
186	#ifdef CONFIG_STM32_ROMFS
187	  /* Mount the romfs partition */
188	
189	  ret = stm32_romfs_initialize();
190	  if (ret < 0)
191	    {
192	      syslog(LOG_ERR, "ERROR: Failed to mount romfs at %s: %d\n",
193	             CONFIG_STM32_ROMFS_MOUNTPOINT, ret);
194	    }
195	#endif
196	
197	#ifdef HAVE_RTC_DRIVER
198	  /* Instantiate the STM32 lower-half RTC driver */
199	
200	  lower = stm32_rtc_lowerhalf();
201	  if (!lower)
202	    {
203	      syslog(LOG_ERR,
204	             "ERROR: Failed to instantiate the RTC lower-half driver\n");
205	      return -ENOMEM;
206	    }
207	  else
208	    {
209	      /* Bind the lower half driver and register the combined RTC driver
210	       * as /dev/rtc0
211	       */
212	
213	      ret = rtc_initialize(0, lower);
214	      if (ret < 0)
215	        {
216	          syslog(LOG_ERR,
217	                 "ERROR: Failed to bind/register the RTC driver: %d\n", ret);
218	          return ret;
219	        }
220	    }
221	#endif
222	
223	#ifdef CONFIG_INPUT_BUTTONS_LOWER
224	  /* Generic lower-half BUTTON driver. Requires INPUT_BUTTONS_LOWER +
225	   * INPUT_BUTTONS + ARCH_BUTTONS + ARCH_IRQBUTTONS. H7A3ZI-Q has only
226	   * the USER button on PC13; IRQ-button support is a follow-up.
227	   */
228	
229	  ret = btn_lower_initialize("/dev/buttons");
230	  if (ret < 0)
231	    {
232	      syslog(LOG_ERR, "ERROR: btn_lower_initialize() failed: %d\n", ret);
233	    }
234	#endif /* CONFIG_INPUT_BUTTONS_LOWER */
235	
236	#ifdef CONFIG_USERLED_LOWER
237	  ret = userled_lower_initialize("/dev/userleds");
238	  if (ret < 0)
239	    {
240	      syslog(LOG_ERR, "ERROR: userled_lower_initialize() failed: %d\n", ret);
241	    }
242	#endif
243	
244	#ifdef CONFIG_ONESHOT
245	  os = oneshot_initialize(2, 10);
246	  if (os != NULL)
247	    {
248	      ret = oneshot_register("/dev/oneshot/0", os);
249	      if (ret < 0)
250	        {
251	          syslog(LOG_ERR, "ERROR: oneshot_register failed: %d\n", ret);
252	        }
253	    }
254	  else
255	    {
256	      syslog(LOG_ERR, "ERROR: oneshot_initialize(TIM2) failed\n");
257	    }
258	#endif
259	
260	#ifdef HAVE_USBHOST
261	  /* Initialize USB host operation.  stm32_usbhost_initialize()
262	   * starts a thread will monitor for USB connection and
263	   * disconnection events.
264	   */
265	
266	  ret = stm32_usbhost_initialize();
267	  if (ret != OK)
268	    {
269	      syslog(LOG_ERR,
270	             "ERROR: Failed to initialize USB host: %d\n",
271	             ret);
272	    }
273	#endif
274	
275	#ifdef HAVE_USBMONITOR
276	  /* Start the USB Monitor */
277	
278	  ret = usbmonitor_start();
279	  if (ret != OK)
280	    {
281	      syslog(LOG_ERR,
282	             "ERROR: Failed to start USB monitor: %d\n",
283	             ret);
284	    }
285	#endif
286	
287	#ifdef CONFIG_ADC
288	  /* Initialize ADC and register the ADC driver. */
289	
290	  ret = stm32_adc_setup();
291	  if (ret < 0)
292	    {
293	      syslog(LOG_ERR, "ERROR: stm32_adc_setup failed: %d\n", ret);
294	    }
295	#endif /* CONFIG_ADC */
296	
297	#ifdef CONFIG_DEV_GPIO
298	  /* Register the GPIO driver */
299	
300	  ret = stm32_gpio_initialize();
301	  if (ret < 0)
302	    {
303	      syslog(LOG_ERR, "Failed to initialize GPIO Driver: %d\n", ret);
304	      return ret;
305	    }
306	#endif
307	
308	#ifdef CONFIG_SENSORS_LSM6DSL
309	  ret = stm32_lsm6dsl_initialize("/dev/lsm6dsl0");
310	  if (ret < 0)
311	    {
312	      syslog(LOG_ERR, "ERROR: Failed to initialize LSM6DSL driver: %d\n",
313	             ret);
314	    }
315	#endif /* CONFIG_SENSORS_LSM6DSL */
316	
317	#ifdef CONFIG_SENSORS_LSM9DS1
318	  ret = stm32_lsm9ds1_initialize();
319	  if (ret < 0)
320	    {
321	      syslog(LOG_ERR, "ERROR: Failed to initialize LSM9DS1 driver: %d\n",
322	             ret);
323	    }
324	#endif /* CONFIG_SENSORS_LSM6DSL */
325	
326	#ifdef CONFIG_SENSORS_LSM303AGR
327	  ret = stm32_lsm303agr_initialize("/dev/lsm303mag0");
328	  if (ret < 0)
329	    {
330	      syslog(LOG_ERR, "ERROR: Failed to initialize LSM303AGR driver: %d\n",
331	             ret);
332	    }
333	#endif /* CONFIG_SENSORS_LSM303AGR */
334	
335	#ifdef CONFIG_PCA9635PW
336	  /* Initialize the PCA9635 chip */
337	
338	  ret = stm32_pca9635_initialize();
339	  if (ret < 0)
340	    {
341	      syslog(LOG_ERR, "ERROR: stm32_pca9635_initialize failed: %d\n", ret);
342	    }
343	#endif
344	
345	#ifdef CONFIG_WL_NRF24L01
346	  ret = stm32_wlinitialize();
347	  if (ret < 0)
348	    {
349	      syslog(LOG_ERR, "ERROR: Failed to initialize wireless driver: %d\n",
350	             ret);
351	    }
352	#endif /* CONFIG_WL_NRF24L01 */
353	
354	#if defined(CONFIG_CDCACM) && !defined(CONFIG_CDCACM_CONSOLE) && \
355	    !defined(CONFIG_CDCACM_COMPOSITE)
356	  /* Initialize CDCACM */
357	
358	  syslog(LOG_INFO, "Initialize CDCACM device\n");
359	
360	  ret = cdcacm_initialize(0, NULL);
361	  if (ret < 0)
362	    {
363	      syslog(LOG_ERR, "ERROR: cdcacm_initialize failed: %d\n", ret);
364	    }
365	#endif /* CONFIG_CDCACM & !CONFIG_CDCACM_CONSOLE */
366	
367	#if defined(CONFIG_RNDIS) && !defined(CONFIG_RNDIS_COMPOSITE)
368	  uint8_t mac[6];
369	  mac[0] = 0xa0; /* TODO */
370	  mac[1] = (CONFIG_NETINIT_MACADDR_2 >> (8 * 0)) & 0xff;
371	  mac[2] = (CONFIG_NETINIT_MACADDR_1 >> (8 * 3)) & 0xff;
372	  mac[3] = (CONFIG_NETINIT_MACADDR_1 >> (8 * 2)) & 0xff;
373	  mac[4] = (CONFIG_NETINIT_MACADDR_1 >> (8 * 1)) & 0xff;
374	  mac[5] = (CONFIG_NETINIT_MACADDR_1 >> (8 * 0)) & 0xff;
375	  usbdev_rndis_initialize(mac);
376	#endif
377	
378	#ifdef CONFIG_MMCSD_SPI
379	  /* Initialize the MMC/SD SPI driver (SPI3 is used) */
380	
381	  ret = stm32_mmcsd_initialize(CONFIG_NSH_MMCSDMINOR);
382	  if (ret < 0)
383	    {
384	      syslog(LOG_ERR, "Failed to initialize SD slot %d: %d\n",
385	             CONFIG_NSH_MMCSDMINOR, ret);
386	    }
387	#endif
388	
389	#ifdef CONFIG_PWM
390	  /* Initialize PWM and register the PWM device. */
391	
392	  ret = stm32_pwm_setup();
393	  if (ret < 0)
394	    {
395	      syslog(LOG_ERR, "ERROR: stm32_pwm_setup() failed: %d\n", ret);
396	    }
397	#endif
398	
399	#ifdef CONFIG_MTD
400	#ifdef HAVE_PROGMEM_CHARDEV
401	  ret = stm32_progmem_init();
402	  if (ret < 0)
403	    {
404	      syslog(LOG_ERR, "ERROR: Failed to initialize MTD progmem: %d\n", ret);
405	    }
406	#endif /* HAVE_PROGMEM_CHARDEV */
407	#endif /* CONFIG_MTD */
408	
409	#ifdef CONFIG_STM32H7_IWDG
410	  /* Initialize the watchdog timer */
411	
412	  stm32_iwdginitialize("/dev/watchdog0", STM32_LSI_FREQUENCY);
413	#endif
414	
415	  return OK;
416	}
