  irq_attach(ARMV8M_IRQ_SVCALL, arm_svcall, NULL);
  irq_attach(ARMV8M_IRQ_HARDFAULT, arm_hardfault, NULL);

  /* And finally, enable interrupts */

  up_irq_enable();
}

/****************************************************************************
 * Name: up_enable_irq
 *
 * Description:
 *   Enable the IRQ specified by 'irq'
 *
 ****************************************************************************/

void up_enable_irq(int irq)
{
  int nvic = irq - NVIC_IRQ_FIRST;
  if (nvic < 0)
    {
      /* Ignore attempts to enable exceptions */

      return;
    }

  putreg32(1 << (nvic & 0x1f), NVIC_IRQ_ENABLE(nvic));
}

/****************************************************************************
 * Name: up_disable_irq
 *
 * Description:
 *   Disable the IRQ specified by 'irq'
 *
 ****************************************************************************/

void up_disable_irq(int irq)
{
  int nvic = irq - NVIC_IRQ_FIRST;
  if (nvic < 0)
    {
      /* Ignore attempts to disable exceptions */

      return;
    }

  putreg32(1 << (nvic & 0x1f), NVIC_IRQ_CLEAR(nvic));
}

