static inline void st_uart_putreg(struct uart_dev_s *dev, uint32_t offset,
                                  uint32_t value)
{
  putreg32(value, STM32N6_USART1_BASE + offset);
}

static inline uint32_t st_uart_getreg(struct uart_dev_s *dev,
                                      uint32_t offset)
{
  return getreg32(STM32N6_USART1_BASE + offset);
}

static int st_uart_setup(struct uart_dev_s *dev)
{
  uint32_t reg;

  /* Enable USART1 clock - set PCLK2 divider */

  /* Configure GPIO: PE5=TX, PE6=RX as AF7 */

  reg = getreg32(STM32N6_GPIOE_BASE + GPIO_MODER);
  reg &= ~(0x3 << (5 * 2)) & ~(0x3 << (6 * 2));
  reg |= (0x2 << (5 * 2)) | (0x2 << (6 * 2));  /* Alternate function */
  putreg32(reg, STM32N6_GPIOE_BASE + GPIO_MODER);

  reg = getreg32(STM32N6_GPIOE_BASE + GPIO_OSPEEDR);
  reg |= (0x3 << (5 * 2)) | (0x3 << (6 * 2));  /* Very high speed */
  putreg32(reg, STM32N6_GPIOE_BASE + GPIO_OSPEEDR);

  reg = getreg32(STM32N6_GPIOE_BASE + GPIO_PUPDR);
  reg &= ~(0x3 << (5 * 2)) & ~(0x3 << (6 * 2));
  reg |= (0x1 << (5 * 2)) | (0x1 << (6 * 2));  /* Pull-up */
  putreg32(reg, STM32N6_GPIOE_BASE + GPIO_PUPDR);

  /* Set AF7 for PE5 (AFRL[5]) and PE6 (AFRL[6]) */

  reg = getreg32(STM32N6_GPIOE_BASE + GPIO_AFRL);
  reg &= ~(0xf << (5 * 4)) & ~(0xf << (6 * 4));
  reg |= (7 << (5 * 4)) | (7 << (6 * 4));
  putreg32(reg, STM32N6_GPIOE_BASE + GPIO_AFRL);

  /* Configure USART1: 115200 8N1, using HSI (64 MHz) as kernel clock */

  st_uart_putreg(dev, USART_CR1, 0);  /* Disable USART */

  /* BRR = fck / baud = 64000000 / 115200 = 556 (approx) */

  st_uart_putreg(dev, USART_BRR, 556);

  /* Enable TX, RX, USART */

  st_uart_putreg(dev, USART_CR1, USART_CR1_UE | USART_CR1_TE | USART_CR1_RE);

  /* Wait for TE and RE acknowledgment */

  while ((st_uart_getreg(dev, USART_ISR) & (USART_ISR_TEACK | USART_ISR_REACK))
         != (USART_ISR_TEACK | USART_ISR_REACK));

  return OK;
}

static void st_uart_shutdown(struct uart_dev_s *dev)
{
  st_uart_putreg(dev, USART_CR1, 0);
}

static int st_uart_attach(struct uart_dev_s *dev)
{
  return OK;
}

static void st_uart_detach(struct uart_dev_s *dev)
{
}

static int st_uart_txready(struct uart_dev_s *dev)
{
  return (st_uart_getreg(dev, USART_ISR) & USART_ISR_TXE) != 0;
}

static void st_uart_txchar(struct uart_dev_s *dev)
{
  struct uart_buffer_s *xmit = &dev->xmit;
  if (xmit->head != xmit->tail)
    {
      st_uart_putreg(dev, USART_TDR, xmit->buffer[xmit->tail]);
      xmit->tail = (xmit->tail + 1) % xmit->size;
    }
}

static void st_uart_txint(struct uart_dev_s *dev, bool enable)
{
}

static int st_uart_rxready(struct uart_dev_s *dev)
{
  return (st_uart_getreg(dev, USART_ISR) & USART_ISR_RXNE) != 0;
}

static void st_uart_rxchar(struct uart_dev_s *dev)
{
  struct uart_buffer_s *recv = &dev->recv;
  uint32_t rdr = st_uart_getreg(dev, USART_RDR);
  uint32_t next = (recv->head + 1) % recv->size;
  if (next != recv->tail)
    {
      recv->buffer[recv->head] = (char)rdr;
      recv->head = next;
    }
}

static void st_uart_rxint(struct uart_dev_s *dev, bool enable)
{
  uint32_t cr1 = st_uart_getreg(dev, USART_CR1);
  if (enable)
    {
      cr1 |= USART_CR1_RXNEIE;
    }
  else
    {
      cr1 &= ~USART_CR1_RXNEIE;
    }
  st_uart_putreg(dev, USART_CR1, cr1);
}

