/* NVIC priority register addresses */

#define NVIC_SYSH4_7_PRIORITY   0xe000ed18
#define NVIC_SYSH8_11_PRIORITY  0xe000ed1c
#define NVIC_SYSH12_15_PRIORITY 0xe000ed20

